<?php
declare(strict_types=1);
namespace App\Controllers\Admin;
use App\Core\{AppKernel,Request,Response};
final class PricesController extends AdminController
{
    public function index(Request$r):Response{$u=$this->requireUser();if($u instanceof Response)return$u;$allowed=AppKernel::access()->accessibleBranchIdsForPermission($u->id??0,'prices.view');if($allowed===[])return$this->requirePermission($u,'prices.view')??throw new \LogicException();$branch=$r->integer('branch_id')?:null;if(is_array($allowed)){if($branch!==null&&!in_array($branch,$allowed,true))return$this->requirePermission($u,'prices.view',$branch)??throw new \LogicException();$branch??=$allowed[0]??null;}$status=$r->query('status','all');$active=$status==='active'?true:($status==='inactive'?false:null);$list=$r->integer('list_id')?:null;$offset=max(0,(int)$r->query('offset','0'));return$this->adminView('admin/pricing/index',['title'=>'Precios','activeNav'=>'prices','user'=>$u,'page'=>AppKernel::pricing()->prices(trim($r->query('q')),$branch,$list,$active,25,$offset),'q'=>trim($r->query('q')),'branchId'=>$branch,'listId'=>$list,'status'=>$status,'allBranches'=>$allowed===null,'branches'=>$this->branches($allowed),'lists'=>AppKernel::pricing()->priceLists()]);}
    public function createForm(Request$r):Response{return$this->form($r,null);}public function editForm(Request$r):Response{return$this->form($r,$r->integer('id'));}
    private function form(Request$r,?int$id):Response{$u=$this->requireUser();if($u instanceof Response)return$u;$price=$id===null?null:AppKernel::pricing()->findPrice($id);if($id!==null&&$price===null)return$this->adminView('admin/error',['title'=>'Precio no encontrado','message'=>'El registro solicitado no existe.','user'=>$u],404);$branch=$price===null?($r->integer('branch_id')?:null):(int)$price['branch_id'];$permission=$id===null?'prices.create':'prices.edit'; $allowed=AppKernel::access()->accessibleBranchIdsForPermission($u->id??0,$permission);if($allowed===[])return$this->requirePermission($u,$permission)??throw new \LogicException();if($branch!==null&&($d=$this->requirePermission($u,$permission,$branch))!==null)return$d;return$this->adminView('admin/pricing/form',['title'=>$id===null?'Nuevo precio':'Editar precio','activeNav'=>'prices','user'=>$u,'price'=>$price,'selectedBranchId'=>$branch,'history'=>$id===null?[]:AppKernel::pricing()->priceHistory($id),'branches'=>$this->branches($allowed),'variants'=>AppKernel::pricing()->variants(trim($r->query('variant_q'))),'lists'=>AppKernel::pricing()->priceLists(false),'taxes'=>AppKernel::pricing()->taxCategories(false)]);}
    public function save(Request$r):Response{$u=$this->requireUser();if($u instanceof Response)return$u;if(($c=$this->requireCsrf($r,$u))!==null)return$c;$id=$r->integer('id')?:null;$branch=$r->integer('branch_id');$permission=$id===null?'prices.create':'prices.edit';if(($d=$this->requirePermission($u,$permission,$branch))!==null)return$d;$input=['branch_id'=>$branch,'variant_id'=>$r->integer('variant_id'),'price_list_id'=>$r->integer('price_list_id'),'tax_category_id'=>$r->integer('tax_category_id'),'amount'=>$r->input('amount'),'tax_included'=>$r->input('tax_included'),'valid_from'=>$r->input('valid_from'),'valid_until'=>$r->input('valid_until')];$version=$id===null?null:$r->integer('lock_version');return$this->run(fn()=>AppKernel::pricingManagement()->savePrice($id,$input,$u->id??0,$version,fn(array$p)=>AppKernel::audit()->record($u->id,$id===null?'prices.create':'prices.edit','price',$p['id'],$branch,'success')),$id===null?'Precio registrado inactivo.':'Precio actualizado.','/admin/prices',$u->id,$id===null?'prices.create':'prices.edit','price',$id,$branch);}
    public function status(Request$r):Response{$u=$this->requireUser();if($u instanceof Response)return$u;if(($c=$this->requireCsrf($r,$u))!==null)return$c;$id=$r->integer('id');$price=AppKernel::pricing()->findPrice($id);if($price===null)return$this->adminView('admin/error',['title'=>'Precio no encontrado','message'=>'El registro no existe.','user'=>$u],404);$branch=(int)$price['branch_id'];if(($d=$this->requirePermission($u,'prices.status',$branch))!==null)return$d;$active=$r->input('active')==='1';return$this->run(fn()=>AppKernel::pricingManagement()->setPriceActive($id,$r->integer('lock_version'),$active,$u->id??0,fn(array$p)=>AppKernel::audit()->record($u->id,$active?'prices.activate':'prices.deactivate','price',$p['id'],$branch,'success')),$active?'Precio activado.':'Precio desactivado.','/admin/prices',$u->id,$active?'prices.activate':'prices.deactivate','price',$id,$branch);}
    public function calculate(Request$r):Response{$u=$this->requireUser();if($u instanceof Response)return$u;$allowed=AppKernel::access()->accessibleBranchIdsForPermission($u->id??0,'prices.view');if($allowed===[])return$this->requirePermission($u,'prices.view')??throw new \LogicException();$branch=$r->integer('branch_id');if($branch&&($d=$this->requirePermission($u,'prices.view',$branch))!==null)return$d;$result=null;$error=null;if($r->integer('variant_id')&&$r->integer('list_id'))try{if(!$branch)throw new \InvalidArgumentException('Selecciona una sucursal para calcular.');$result=AppKernel::pricingManagement()->quote($branch,$r->integer('variant_id'),$r->integer('list_id'),$r->query('date')?:date('Y-m-d'),$r->query('quantity','1'));}catch(\InvalidArgumentException $e){$error=$e->getMessage();}return$this->adminView('admin/pricing/calculate',['title'=>'Cálculo comercial','activeNav'=>'prices','user'=>$u,'result'=>$result,'error'=>$error,'branches'=>$this->branches($allowed),'variants'=>AppKernel::pricing()->variants(),'lists'=>AppKernel::pricing()->priceLists(false),'values'=>['branch_id'=>$branch,'variant_id'=>$r->integer('variant_id'),'list_id'=>$r->integer('list_id'),'date'=>$r->query('date')?:date('Y-m-d'),'quantity'=>$r->query('quantity','1')]]);}
    private function branches(?array$allowed):array{$rows=AppKernel::pricing()->branches();return$allowed===null?$rows:array_values(array_filter($rows,fn(array$b)=>in_array((int)$b['id'],$allowed,true)));}
}
